use novel_storage::{Storage,Scene,SyncCursor};
use serde_json::json;
async fn store()->(tempfile::TempDir,Storage){let d=tempfile::tempdir().unwrap();let s=Storage::open(&d.path().join("metadata.sqlite")).await.unwrap();(d,s)}
fn scene(title:&str)->Scene{Scene{schema_version:1,title:title.into(),document:json!({"type":"doc","content":[{"type":"paragraph","attrs":{"dir":"rtl","lang":"ar"},"content":[{"type":"text","text":"مِ 中文 𠀀 👩🏽‍🚀","marks":[{"type":"bold"}]}]}]})}}
async fn exchange(s:&Storage,r:&Storage,pid:&str,after:i64){let epoch=s.sync_cursor().await.unwrap().epoch;let local=r.sync_cursor().await.unwrap().epoch;let page=s.pull_revisions(pid,SyncCursor{epoch:epoch.clone(),sequence:after},100).await.unwrap();r.ingest_revisions(pid,&local,&epoch,s.sync_manifest(pid).await.unwrap(),page.revisions).await.unwrap();}
#[tokio::test]
async fn deferred_single_head_chapter_order_requires_explicit_exact_checked_replay(){
    let (_d,s)=store().await;let (_e,r)=store().await;let p=s.create_project("Metadata").await.unwrap();let a=s.create_chapter(&p.id,"A").await.unwrap();let b=s.create_chapter(&p.id,"B").await.unwrap();let c=s.create_chapter(&p.id,"C").await.unwrap();let moved=s.create_scene(&a.id,scene("Moved")).await.unwrap();let one=s.create_scene(&b.id,scene("One")).await.unwrap();let two=s.create_scene(&b.id,scene("Two")).await.unwrap();exchange(&s,&r,&p.id,0).await;let after=s.sync_cursor().await.unwrap().sequence;
    let sc=s.scene_arrangement_snapshot(&p.id,&moved.id).await.unwrap();let rc=r.scene_arrangement_snapshot(&p.id,&moved.id).await.unwrap();s.arrange_scene(&sc,&b.id,0).await.unwrap();r.arrange_scene(&rc,&c.id,0).await.unwrap();exchange(&s,&r,&p.id,after).await;
    let retained=r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap();assert_eq!(retained.heads.len(),1);let payload=r.load_entity_revision(&p.id,&b.id,"chapter",&retained.heads[0]).await.unwrap().payload;assert_eq!(payload["order"],json!([moved.id,one.id,two.id]));assert_ne!(retained.projection,payload);
    let marker=r.sync_cursor().await.unwrap();assert!(r.resolve_metadata_checked(&retained,payload.clone()).await.unwrap_err().contains("placements"));assert_eq!(r.sync_cursor().await.unwrap(),marker);
    let placement=r.metadata_resolution_snapshot(&p.id,&moved.id,"scenePlacement").await.unwrap();assert_eq!(placement.heads.len(),2);r.resolve_metadata_checked(&placement,json!({"chapterId":b.id,"position":0})).await.unwrap();assert_eq!(r.metadata_heads(&p.id,&b.id,"chapter").await.unwrap().revision_ids,retained.heads,"Placement resolution never silently replays a chapter order");
    assert!(r.resolve_metadata_checked(&retained,payload.clone()).await.unwrap_err().contains("changed"));
    // Create a definite current-order difference without changing the retained chapter head.
    r.move_scene(&moved.id,&b.id,2).await.unwrap();let fresh=r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap();assert_ne!(fresh.projection,payload);let marker=r.sync_cursor().await.unwrap();let mut forged=payload.clone();forged["title"]=json!("Unreviewed title");assert!(r.resolve_metadata_checked(&fresh,forged).await.unwrap_err().contains("exact retained"));assert_eq!(r.sync_cursor().await.unwrap(),marker);
    let revision=r.resolve_metadata_checked(&fresh,payload.clone()).await.unwrap();assert_eq!(r.metadata_heads(&p.id,&b.id,"chapter").await.unwrap().revision_ids,vec![revision.clone()]);assert_eq!(r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap().projection,payload);assert_eq!(r.load_scene(&moved.id).await.unwrap().revision_id,moved.revision_id);assert_eq!(r.load_scene(&moved.id).await.unwrap().scene,moved.scene);
    let changes=r.changes(marker.sequence,100).await.unwrap();assert_eq!(changes.len(),1);assert_eq!(changes[0].id,revision);assert_eq!(changes[0].parents,fresh.heads);assert_eq!(changes[0].operation,"resolve");
    let already=r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap();assert!(r.resolve_metadata_checked(&already,payload).await.unwrap_err().contains("already applied"));
}
#[tokio::test]
async fn competing_chapter_orders_require_settled_placement_dependencies_and_fresh_preview(){
    let (_d,s)=store().await;let (_e,r)=store().await;let p=s.create_project("Metadata").await.unwrap();let a=s.create_chapter(&p.id,"A").await.unwrap();let b=s.create_chapter(&p.id,"B").await.unwrap();let c=s.create_chapter(&p.id,"C").await.unwrap();let moved=s.create_scene(&a.id,scene("Moved")).await.unwrap();let one=s.create_scene(&b.id,scene("One")).await.unwrap();let two=s.create_scene(&b.id,scene("Two")).await.unwrap();exchange(&s,&r,&p.id,0).await;let after=s.sync_cursor().await.unwrap().sequence;
    let sc=s.scene_arrangement_snapshot(&p.id,&moved.id).await.unwrap();let rc=r.scene_arrangement_snapshot(&p.id,&moved.id).await.unwrap();s.arrange_scene(&sc,&b.id,0).await.unwrap();r.arrange_scene(&rc,&c.id,0).await.unwrap();r.reorder_scenes(&b.id,vec![two.id.clone(),one.id.clone()]).await.unwrap();exchange(&s,&r,&p.id,after).await;
    let capture=r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap();assert_eq!(capture.heads.len(),2);let payload=json!({"title":"B resolved مِ 中文","order":[moved.id,one.id,two.id]});let before=r.open_project_index(&p.id).await.unwrap();let marker=r.sync_cursor().await.unwrap();
    assert!(r.resolve_metadata(&p.id,&b.id,"chapter",payload.clone(),capture.heads.clone()).await.unwrap_err().contains("placements"));assert!(r.resolve_metadata_checked(&capture,payload.clone()).await.unwrap_err().contains("placements"));assert_eq!(r.open_project_index(&p.id).await.unwrap(),before);assert_eq!(r.sync_cursor().await.unwrap(),marker);
    let placement=r.metadata_resolution_snapshot(&p.id,&moved.id,"scenePlacement").await.unwrap();r.resolve_metadata_checked(&placement,json!({"chapterId":b.id,"position":0})).await.unwrap();assert!(r.resolve_metadata_checked(&capture,payload.clone()).await.unwrap_err().contains("changed"));let fresh=r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap();r.resolve_metadata_checked(&fresh,payload).await.unwrap();assert_eq!(r.open_project_index(&p.id).await.unwrap().chapters.iter().find(|c|c.id==b.id).unwrap().title,"B resolved مِ 中文");assert_eq!(r.load_scene(&moved.id).await.unwrap().scene,moved.scene);
    // A placement-only edit changes ordering dependencies even without a chapter revision.
    let chapter=r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap();r.move_scene(&one.id,&b.id,0).await.unwrap();let current=r.load_entity_revision(&p.id,&b.id,"chapter",&chapter.heads[0]).await.unwrap().payload;let marker=r.sync_cursor().await.unwrap();assert!(r.resolve_metadata_checked(&chapter,current).await.unwrap_err().contains("changed"));assert_eq!(r.sync_cursor().await.unwrap(),marker);
}
#[tokio::test]
async fn explicit_current_projection_acknowledges_incompatible_single_head_membership(){
    let (_d,s)=store().await;let (_e,r)=store().await;let p=s.create_project("Metadata").await.unwrap();let a=s.create_chapter(&p.id,"A").await.unwrap();let b=s.create_chapter(&p.id,"B").await.unwrap();let c=s.create_chapter(&p.id,"C").await.unwrap();let moved=s.create_scene(&a.id,scene("Moved")).await.unwrap();let one=s.create_scene(&b.id,scene("One")).await.unwrap();exchange(&s,&r,&p.id,0).await;let after=s.sync_cursor().await.unwrap().sequence;
    let sc=s.scene_arrangement_snapshot(&p.id,&moved.id).await.unwrap();let rc=r.scene_arrangement_snapshot(&p.id,&moved.id).await.unwrap();s.arrange_scene(&sc,&b.id,0).await.unwrap();r.arrange_scene(&rc,&c.id,0).await.unwrap();exchange(&s,&r,&p.id,after).await;
    let placement=r.metadata_resolution_snapshot(&p.id,&moved.id,"scenePlacement").await.unwrap();r.resolve_metadata_checked(&placement,json!({"chapterId":c.id,"position":0})).await.unwrap();
    let captured=r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap();assert_eq!(captured.heads.len(),1);let retained=r.load_entity_revision(&p.id,&b.id,"chapter",&captured.heads[0]).await.unwrap().payload;assert_eq!(retained["order"],json!([moved.id,one.id]));assert_eq!(captured.projection["order"],json!([one.id]));let marker=r.sync_cursor().await.unwrap();
    assert!(r.resolve_metadata_checked(&captured,retained.clone()).await.unwrap_err().contains("unauthorized"));assert_eq!(r.sync_cursor().await.unwrap(),marker);
    let mut edited=captured.projection.clone();edited["title"]=json!("Unreviewed change");assert!(r.resolve_metadata_checked(&captured,edited).await.unwrap_err().contains("exact retained"));assert_eq!(r.sync_cursor().await.unwrap(),marker);
    let revision=r.resolve_metadata_checked(&captured,captured.projection.clone()).await.unwrap();let new=r.load_entity_revision(&p.id,&b.id,"chapter",&revision).await.unwrap();assert_eq!(new.parents,captured.heads);assert_eq!(new.payload,captured.projection);assert_eq!(r.load_entity_revision(&p.id,&b.id,"chapter",&captured.heads[0]).await.unwrap().payload,retained);assert_eq!(r.metadata_resolution_snapshot(&p.id,&b.id,"chapter").await.unwrap().projection,captured.projection);
    let index=r.open_project_index(&p.id).await.unwrap();assert_eq!(index.scenes.iter().find(|s|s.id==moved.id).unwrap().chapter_id,c.id);assert_eq!(r.load_scene(&moved.id).await.unwrap().scene,moved.scene);assert_eq!(r.load_scene(&moved.id).await.unwrap().revision_id,moved.revision_id);
}
